import json
def transform(g0):
    g=[row[:] for row in g0]; h,w=len(g),len(g[0])
    ms=[(r,c) for r in range(h) for c in range(w) if g0[r][c]==1]
    # candidate aligned pairs sorted by distance; greedy, each marker used once
    cands=[]
    for i in range(len(ms)):
        for j in range(i+1,len(ms)):
            (r1,c1),(r2,c2)=ms[i],ms[j]
            if r1==r2 or c1==c2:
                cands.append((abs(r1-r2)+abs(c1-c2),i,j))
    cands.sort()
    used=set(); segs=[]
    for d,i,j in cands:
        if i in used or j in used: continue
        used.add(i); used.add(j)
        (r1,c1),(r2,c2)=ms[i],ms[j]
        segs.append((r1,c1,r2,c2))
    for r1,c1,r2,c2 in segs:
        if r1==r2:
            for c in range(min(c1,c2),max(c1,c2)+1): g[r1][c]=1
        else:
            for r in range(min(r1,r2),max(r1,r2)+1): g[r][c1]=1
    seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g0[r][c]==2 and not seen[r][c]:
                comp=[]; st=[(r,c)]; seen[r][c]=True; crossed=False
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    if g[a][b]==1: crossed=True
                    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                        if 0<=x<h and 0<=y<w and g0[x][y]==2 and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                if crossed:
                    for a,b in comp: g[a][b]=1
    return g
